
# genesis_agent1_setup.py
# Creates every Agent 1 object in a catalog, and refuses to run when config is empty.
#
# The DDL below was GENERATED from the working dev tables with SHOW CREATE TABLE,
# not written by hand, so a fresh environment gets exactly the dev structure.
#
# Two lessons from the DRA, applied here before production:
#   1. A table that only existed because someone cloned it made every agent fail
#      in a fresh sandbox. ensure_tables() creates every object itself.
#   2. An empty config table let a run report success having done nothing.
#      preflight() stops the run with a plain message instead.
#
# Existing tables are NEVER altered: tables use CREATE TABLE IF NOT EXISTS, so
# running this against production is a no-op for anything already there.

SCHEMAS = ['market_config', 'market_bronze', 'market_silver', 'market_gold']
VOLUMES = ["market_config.code", "market_config.exports"]
TABLE_ORDER = ['market_config.source_registry', 'market_config.source_selectors', 'market_config.source_health', 'market_config.accelerator_catalog', 'market_config.slug_lists', 'market_config.processor_backlog', 'market_config.query_queue', 'market_config.job', 'market_config.job_item', 'market_config.session_limit', 'market_bronze.reference_pages', 'market_silver.reference_facts', 'market_silver.processor_detail', 'market_silver.entity_embeddings']
VIEW_ORDER = ['market_config.slug_device_class', 'market_gold.processor_reference']
DDL = {'market_config.source_registry': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.source_registry (\n  source_name STRING COLLATE UTF8_BINARY,\n  agent STRING COLLATE UTF8_BINARY,\n  url_method STRING COLLATE UTF8_BINARY COMMENT 'constructed = build the URL from the chip name; slug_lookup = find it in accelerator_catalog with the strict matcher',\n  url_pattern STRING COLLATE UTF8_BINARY COMMENT 'placeholders: company, family, model_number, slug, kind',\n  key_transform STRING COLLATE UTF8_BINARY COMMENT 'how the chip name is normalised before substitution',\n  priority INT COMMENT 'order the agent works through sources; every source that answers is recorded',\n  is_current BOOLEAN COMMENT 'false parks a source without deleting it',\n  note STRING COLLATE UTF8_BINARY,\n  updated_at TIMESTAMP,\n  device_scope STRING COLLATE UTF8_BINARY,\n  verify_in_title BOOLEAN)\nUSING delta\nCOMMENT 'Where each fact is sourced from, as data not code. Changing a source or adding a\nsite is a row change, never a deployment. Route and pacing live in source_health because\nthose change with conditions while these patterns do not.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.source_selectors': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.source_selectors (\n  source_name STRING COLLATE UTF8_BINARY,\n  fact_name STRING COLLATE UTF8_BINARY,\n  fact_unit STRING COLLATE UTF8_BINARY,\n  extract_method STRING COLLATE UTF8_BINARY COMMENT 'regex today; css or llm_fallback later',\n  expression STRING COLLATE UTF8_BINARY COMMENT 'the pattern applied to the stored page text',\n  post_process STRING COLLATE UTF8_BINARY COMMENT 'strip commas, int, float',\n  is_current BOOLEAN,\n  updated_at TIMESTAMP)\nUSING delta\nCOMMENT 'One row per fact per source. A site layout change is an UPDATE here, after which\nfacts rebuild from pages already in reference_pages with no re-fetch.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.source_health': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.source_health (\n  source_name STRING COLLATE UTF8_BINARY,\n  state STRING COLLATE UTF8_BINARY COMMENT 'healthy, degraded, excluded',\n  consecutive_failures INT COMMENT 'three moves a source to degraded',\n  last_success_at TIMESTAMP,\n  last_failure_at TIMESTAMP,\n  last_failure_reason STRING COLLATE UTF8_BINARY,\n  required_route STRING COLLATE UTF8_BINARY COMMENT 'direct, unblocker or none',\n  min_seconds_between_requests INT COMMENT 'pacing, per source, shared by all agents')\nUSING delta\nCOMMENT 'Shared circuit breaker. required_route records what we learned in testing so no\nagent repeats a doomed direct attempt.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.accelerator_catalog': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.accelerator_catalog (\n  slug STRING COLLATE UTF8_BINARY COMMENT 'nanoreview path segment',\n  kind STRING COLLATE UTF8_BINARY COMMENT 'soc, cpu or gpu',\n  display_name STRING COLLATE UTF8_BINARY,\n  source_name STRING COLLATE UTF8_BINARY,\n  first_seen DATE,\n  last_seen DATE)\nUSING delta\nCOMMENT 'Discovered slug catalogue. Agent 1 uses soc and cpu, Agent 5 uses gpu.\nBuilt once, refreshed occasionally.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0',\n  'delta.workloadBasedColumns.deltaFileStatistics' = '`slug`')\n", 'market_config.slug_lists': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.slug_lists (\n  slug STRING COLLATE UTF8_BINARY,\n  list_name STRING COLLATE UTF8_BINARY COMMENT 'soc_rating, cpu_laptop, cpu_desktop, gpu_laptop, gpu_desktop',\n  seen_at TIMESTAMP)\nUSING delta\nCOMMENT 'Which nanoreview ranking list each slug appeared on. A slug can be on several.\ndevice_class is derived from this, not from a single kind field: storing one kind\nexcluded the correct answer twice (Apple M5 Max tagged gpu, Snapdragon X Elite tagged cpu).'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.processor_backlog': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.processor_backlog (\n  processor_key STRING COLLATE UTF8_BINARY COMMENT 'company|family|model_number',\n  company STRING COLLATE UTF8_BINARY,\n  family STRING COLLATE UTF8_BINARY,\n  model_number STRING COLLATE UTF8_BINARY,\n  device_scope STRING COLLATE UTF8_BINARY COMMENT 'computer or mobile, from which list it came',\n  origin STRING COLLATE UTF8_BINARY COMMENT 'genesis_sheet, nanoreview_catalog, or observations',\n  added_at TIMESTAMP)\nUSING delta\nCOMMENT 'Work list for Agent 1. Three origins feed it: the Genesis reference sheet and the\nnanoreview catalogue today, and the observations query once the marketplace pipelines run.\nThe agent reads the backlog, never a single source, so adding an origin changes nothing.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.query_queue': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.query_queue (\n  query_id STRING COLLATE UTF8_BINARY COMMENT 'sha256 of the normalised raw query, so the same ask twice is one row',\n  raw_query STRING COLLATE UTF8_BINARY COMMENT 'exactly what the customer sent, unmodified',\n  parsed_company STRING COLLATE UTF8_BINARY,\n  parsed_family STRING COLLATE UTF8_BINARY,\n  parsed_model STRING COLLATE UTF8_BINARY,\n  device_class STRING COLLATE UTF8_BINARY COMMENT 'computer or mobile, derived at query time',\n  matched_key STRING COLLATE UTF8_BINARY COMMENT 'the processor_key we resolved it to, null while queued',\n  matched_slug STRING COLLATE UTF8_BINARY COMMENT 'the source slug the matcher accepted',\n  match_score DOUBLE COMMENT 'similarity of the accepted candidate',\n  status STRING COLLATE UTF8_BINARY COMMENT 'matched, queued, resolved, unresolvable',\n  attempts INT COMMENT 'how many monthly runs have tried this',\n  first_seen_at TIMESTAMP,\n  last_seen_at TIMESTAMP COMMENT 'updated when the same query is asked again',\n  resolved_at TIMESTAMP,\n  resolved_in_run STRING COLLATE UTF8_BINARY COMMENT 'which monthly run resolved it',\n  times_asked INT COMMENT 'demand signal: how often customers have asked',\n  note STRING COLLATE UTF8_BINARY)\nUSING delta\nCOMMENT 'Customer queries the agent could not answer from the database. A queued row is\nadded to the backlog by the monthly run, resolved like any other chip, then flipped to\nresolved. After two failed monthly attempts a row becomes unresolvable and is no longer\nretried. times_asked shows which missing chips customers actually want.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.job': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.job (\n  job_id STRING COLLATE UTF8_BINARY COMMENT '32 random hex chars. NEVER shown to an external customer; it lives in their browser session. Random so ids cannot be iterated to read another submission.',\n  owner_type STRING COLLATE UTF8_BINARY COMMENT 'genesis_user, session, or api',\n  owner_id STRING COLLATE UTF8_BINARY COMMENT 'a Genesis username, a random session token, or a service name',\n  entry_point STRING COLLATE UTF8_BINARY COMMENT 'chat, csv, or api',\n  raw_input STRING COLLATE UTF8_BINARY COMMENT 'what was submitted, or a description of the file',\n  chip_count INT,\n  status STRING COLLATE UTF8_BINARY COMMENT 'queued, running, complete, rejected, failed',\n  submitted_at TIMESTAMP,\n  started_at TIMESTAMP,\n  completed_at TIMESTAMP,\n  result_json_path STRING COLLATE UTF8_BINARY,\n  result_file_path STRING COLLATE UTF8_BINARY,\n  note STRING COLLATE UTF8_BINARY COMMENT 'e.g. capped at 100, 114 rows not processed')\nUSING delta\nCOMMENT 'One row per submission. Delivery, not data: a job finishes in minutes while a\nqueued chip may wait for the monthly run. Access is by owner_id: results are returned\nonly to a caller presenting the same identity or session token.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.job_item': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.job_item (\n  job_id STRING COLLATE UTF8_BINARY,\n  seq INT COMMENT 'position within the job',\n  raw_text STRING COLLATE UTF8_BINARY COMMENT 'the chip as the customer wrote it',\n  parsed_company STRING COLLATE UTF8_BINARY,\n  parsed_family STRING COLLATE UTF8_BINARY,\n  parsed_model STRING COLLATE UTF8_BINARY,\n  status STRING COLLATE UTF8_BINARY COMMENT 'found, queued, no_processor, unresolvable',\n  matched_key STRING COLLATE UTF8_BINARY,\n  cores INT,\n  single_core INT,\n  multi_core INT,\n  source_names STRING COLLATE UTF8_BINARY COMMENT 'which sources the facts came from',\n  match_score DOUBLE,\n  created_at TIMESTAMP)\nUSING delta\nCOMMENT 'One row per CHIP asked about, not per query, so a three-chip comparison is one\njob with three items and the result downloads as a proper table. A queued item also\nwrites to query_queue, which is how customer demand reaches the monthly run.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.session_limit': "CREATE TABLE IF NOT EXISTS __CAT__.market_config.session_limit (\n  owner_id STRING COLLATE UTF8_BINARY,\n  owner_type STRING COLLATE UTF8_BINARY,\n  window_start TIMESTAMP COMMENT 'the hour this count belongs to',\n  queries_used INT,\n  jobs_used INT,\n  last_seen_at TIMESTAMP,\n  blocked BOOLEAN)\nUSING delta\nCOMMENT 'Rate limit for EXTERNAL sessions only: 20 queries and 3 jobs per hour, enough\nfor a real demo and not enough to hammer sources through a public link. Internal staff\nand API callers are recorded but not limited.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_bronze.reference_pages': "CREATE TABLE IF NOT EXISTS __CAT__.market_bronze.reference_pages (\n  page_id STRING COLLATE UTF8_BINARY COMMENT 'sha256(url||fetched_at)[:24]',\n  url STRING COLLATE UTF8_BINARY,\n  source_name STRING COLLATE UTF8_BINARY,\n  http_status INT COMMENT 'failed fetches are kept: they are the block evidence',\n  fetch_route STRING COLLATE UTF8_BINARY COMMENT 'direct or unblocker',\n  content_bytes INT,\n  html STRING COLLATE UTF8_BINARY COMMENT 'the full page as fetched',\n  fetched_at TIMESTAMP)\nUSING delta\nCOMMENT 'Shared page cache, append only. A parser fix re-reads from here instead of\nre-fetching, which matters because Geekbench and nanoreview rate limit us.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_silver.reference_facts': "CREATE TABLE IF NOT EXISTS __CAT__.market_silver.reference_facts (\n  fact_id STRING COLLATE UTF8_BINARY COMMENT 'sha256(subject_key||agent||fact_name||source_name)[:24]',\n  subject_type STRING COLLATE UTF8_BINARY COMMENT 'processor, model, configuration, spec',\n  subject_key STRING COLLATE UTF8_BINARY COMMENT 'e.g. Intel|Core i7|4980HQ',\n  agent STRING COLLATE UTF8_BINARY COMMENT 'agent_1_processor .. agent_5_ai_gpu, or supervisor',\n  fact_name STRING COLLATE UTF8_BINARY COMMENT 'cores, single_core_score, multi_core_score, ...',\n  fact_value STRING COLLATE UTF8_BINARY COMMENT 'stored as text so one table holds every fact type',\n  fact_unit STRING COLLATE UTF8_BINARY COMMENT 'count, score, USD, year',\n  source_name STRING COLLATE UTF8_BINARY COMMENT 'PassMark, Geekbench, nanoreview, ...',\n  source_url STRING COLLATE UTF8_BINARY COMMENT 'the exact URL fetched. Source grounding.',\n  retrieved_at TIMESTAMP,\n  is_ruling BOOLEAN COMMENT 'true only on a supervisory ruling row',\n  ruling_reason STRING COLLATE UTF8_BINARY COMMENT 'the supervisor stated reason, or a not-found note')\nUSING delta\nCOMMENT 'Shared fact store for all five reference agents. One row per fact per source.\nNothing is averaged and nothing is overwritten, so disagreement stays visible.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0',\n  'delta.workloadBasedColumns.deltaFileStatistics' = '`fact_value`')\n", 'market_silver.processor_detail': "CREATE TABLE IF NOT EXISTS __CAT__.market_silver.processor_detail (\n  fact_id STRING COLLATE UTF8_BINARY COMMENT 'join to reference_facts',\n  processor_key STRING COLLATE UTF8_BINARY,\n  company STRING COLLATE UTF8_BINARY,\n  family STRING COLLATE UTF8_BINARY,\n  model_number STRING COLLATE UTF8_BINARY,\n  source_name STRING COLLATE UTF8_BINARY,\n  source_url STRING COLLATE UTF8_BINARY,\n  matched_slug STRING COLLATE UTF8_BINARY COMMENT 'nanoreview only; blank where the URL is constructed',\n  raw_value STRING COLLATE UTF8_BINARY COMMENT 'the text the number was read from',\n  parse_method STRING COLLATE UTF8_BINARY COMMENT 'selector or llm_fallback',\n  fetch_route STRING COLLATE UTF8_BINARY,\n  page_id STRING COLLATE UTF8_BINARY COMMENT 'join to reference_pages',\n  retrieved_at TIMESTAMP)\nUSING delta\nCOMMENT 'Agent 1 grounding. page_id reopens the exact saved page behind every number.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_silver.entity_embeddings': "CREATE TABLE IF NOT EXISTS __CAT__.market_silver.entity_embeddings (\n  entity_type STRING COLLATE UTF8_BINARY COMMENT 'slug, processor, model, configuration, query',\n  entity_key STRING COLLATE UTF8_BINARY COMMENT 'the nanoreview slug, or Company|Family|Model, or a query id',\n  entity_kind STRING COLLATE UTF8_BINARY COMMENT 'for slugs: soc, cpu or gpu. Null otherwise.',\n  display_text STRING COLLATE UTF8_BINARY COMMENT 'the text that was embedded, human readable',\n  embedding ARRAY<DOUBLE>,\n  model_name STRING COLLATE UTF8_BINARY COMMENT 'which embedding model produced this vector',\n  dim INT,\n  created_at TIMESTAMP)\nUSING delta\nCOMMENT 'Persisted vectors. Embeddings propose candidate matches for messy or misspelled\ninput; the strict matcher then decides. Serves slug lookup and customer queries.'\nDEFAULT COLLATION UTF8_BINARY\nTBLPROPERTIES (\n  'delta.enableDeletionVectors' = 'true',\n  'delta.enableRowTracking' = 'true',\n  'delta.feature.appendOnly' = 'supported',\n  'delta.feature.deletionVectors' = 'supported',\n  'delta.feature.domainMetadata' = 'supported',\n  'delta.feature.invariants' = 'supported',\n  'delta.feature.rowTracking' = 'supported',\n  'delta.minReaderVersion' = '3',\n  'delta.minWriterVersion' = '7',\n  'delta.parquet.compression.codec' = 'zstd',\n  'delta.parquet.format.version' = '2.12.0',\n  'delta.parquet.format.version.afe.internal' = '2.12.0')\n", 'market_config.slug_device_class': 'CREATE OR REPLACE VIEW market_config.slug_device_class (\n  slug COMMENT \'nanoreview path segment\',\n  device_class,\n  is_gpu,\n  source_lists)\nDEFAULT COLLATION UTF8_BINARY\nWITH SCHEMA COMPENSATION\nAS WITH lists AS (\n  SELECT slug,\n         CASE WHEN MAX(CASE WHEN list_name=\'soc_rating\' THEN 1 ELSE 0 END)=1\n              THEN \'mobile\' ELSE \'computer\' END AS device_class,\n         MAX(CASE WHEN list_name LIKE \'gpu%\' THEN 1 ELSE 0 END)=1 AS is_gpu,\n         collect_set(list_name) AS source_lists\n    FROM __CAT__.market_config.slug_lists GROUP BY slug)\nSELECT c.slug,\n       COALESCE(l.device_class,\n                CASE WHEN c.kind=\'soc\' THEN \'mobile\' ELSE \'computer\' END) AS device_class,\n       -- a slug naming a GPU core count IS a gpu entry, whichever list it was filed on.\n       -- nanoreview mis-filed two of these under cpu_laptop because its own typo\n       -- ("sore" for "core") broke their categorisation.\n       CASE WHEN c.slug RLIKE \'(gpu|sore-gpu)\' THEN TRUE\n            ELSE COALESCE(l.is_gpu, c.kind=\'gpu\') END AS is_gpu,\n       COALESCE(l.source_lists, array(\'fallback_from_kind\')) AS source_lists\n  FROM __CAT__.market_config.accelerator_catalog c\n  LEFT JOIN lists l ON l.slug = c.slug\n', 'market_gold.processor_reference': "CREATE OR REPLACE VIEW market_gold.processor_reference (\n  processor_key COMMENT 'company|family|model_number',\n  processor_brand,\n  processor_family,\n  processor_number,\n  join_key,\n  device_class COMMENT 'computer or mobile, from which list it came',\n  cores,\n  threads,\n  geekbench_single,\n  geekbench_multi,\n  geekbench_version,\n  geekbench_source COMMENT 'PassMark, Geekbench, nanoreview, ...',\n  geekbench_url,\n  passmark_single,\n  passmark_multi,\n  passmark_url,\n  last_updated)\nCOMMENT 'One row per processor, keyed brand|family|number as the Genesis table design requires. The contract for MSV and the AI models: join on join_key. Geekbench columns follow the rule Geekbench 7 if available, else Geekbench 6, else any other Geekbench, always as a single and multi pair from one source. PassMark is a different scale and has its own columns. Genesis reference sheet values are excluded; they are a validation set.'\nDEFAULT COLLATION UTF8_BINARY\nWITH SCHEMA COMPENSATION\nAS WITH f AS (\n  SELECT subject_key, source_name, fact_name, fact_value, source_url, retrieved_at\n    FROM __CAT__.market_silver.reference_facts\n   WHERE agent = 'agent_1_processor' AND source_name <> 'Genesis reference sheet'),\nper_source AS (\n  SELECT subject_key, source_name,\n         MAX(CASE WHEN fact_name = 'single_core_score' THEN CAST(fact_value AS INT) END) AS single,\n         MAX(CASE WHEN fact_name = 'multi_core_score'  THEN CAST(fact_value AS INT) END) AS multi,\n         MAX(CASE WHEN fact_name = 'cores'   THEN CAST(fact_value AS INT) END) AS cores,\n         MAX(CASE WHEN fact_name = 'threads' THEN CAST(fact_value AS INT) END) AS threads,\n         MAX(source_url) AS url\n    FROM f GROUP BY subject_key, source_name),\ngb AS (\n  SELECT subject_key, single AS geekbench_single, multi AS geekbench_multi,\n         CASE source_name WHEN 'Geekbench' THEN '7' WHEN 'nanoreview' THEN '6'\n              ELSE 'unversioned' END AS geekbench_version,\n         source_name AS geekbench_source, url AS geekbench_url\n    FROM per_source\n   WHERE source_name IN ('Geekbench', 'nanoreview') AND single IS NOT NULL AND multi IS NOT NULL\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY subject_key ORDER BY\n          CASE source_name WHEN 'Geekbench' THEN 1 WHEN 'nanoreview' THEN 2 ELSE 3 END) = 1),\npm AS (\n  SELECT subject_key, single AS passmark_single, multi AS passmark_multi, url AS passmark_url\n    FROM per_source WHERE source_name = 'PassMark'),\ncr AS (\n  SELECT subject_key, cores FROM per_source WHERE cores IS NOT NULL\n  QUALIFY ROW_NUMBER() OVER (PARTITION BY subject_key ORDER BY\n          CASE source_name WHEN 'nanoreview' THEN 1 WHEN 'PassMark' THEN 2 ELSE 3 END) = 1),\nth AS (SELECT subject_key, MAX(threads) AS threads FROM per_source GROUP BY subject_key),\nup AS (SELECT subject_key, MAX(retrieved_at) AS last_updated FROM f GROUP BY subject_key)\nSELECT b.processor_key,\n       b.company      AS processor_brand,\n       b.family       AS processor_family,\n       b.model_number AS processor_number,\n       regexp_replace(lower(concat(b.company, b.family, coalesce(b.model_number, ''))),\n                      '[^a-z0-9]', '') AS join_key,\n       b.device_scope AS device_class,\n       cr.cores, th.threads,\n       gb.geekbench_single, gb.geekbench_multi, gb.geekbench_version,\n       gb.geekbench_source, gb.geekbench_url,\n       pm.passmark_single, pm.passmark_multi, pm.passmark_url,\n       up.last_updated\n  FROM __CAT__.market_config.processor_backlog b\n  LEFT JOIN gb ON gb.subject_key = b.processor_key\n  LEFT JOIN pm ON pm.subject_key = b.processor_key\n  LEFT JOIN cr ON cr.subject_key = b.processor_key\n  LEFT JOIN th ON th.subject_key = b.processor_key\n  LEFT JOIN up ON up.subject_key = b.processor_key\n"}

CHECKS = [
    ("source registry has current Agent 1 sources",
     "SELECT COUNT(*) FROM __CAT__.market_config.source_registry "
     "WHERE agent = 'agent_1_processor' AND is_current", 3),
    ("source selectors are loaded",
     "SELECT COUNT(*) FROM __CAT__.market_config.source_selectors WHERE is_current", 6),
    ("source health is seeded",
     "SELECT COUNT(*) FROM __CAT__.market_config.source_health", 3),
    ("slug catalogue is loaded",
     "SELECT COUNT(*) FROM __CAT__.market_config.accelerator_catalog", 500),
    ("slug list membership is loaded",
     "SELECT COUNT(*) FROM __CAT__.market_config.slug_lists", 500),
    ("slug embeddings exist",
     "SELECT COUNT(*) FROM __CAT__.market_silver.entity_embeddings "
     "WHERE entity_type = 'slug' AND model_name = 'databricks-bge-large-en'", 500),
    ("processor backlog is not empty",
     "SELECT COUNT(*) FROM __CAT__.market_config.processor_backlog", 1),
]


def ensure_tables(spark, catalog):
    # Set the session catalog first. A workspace can default to its own auto-created
    # catalog (dbw_genesis_devp in dev), and any unqualified name would then resolve
    # there and fail with SCHEMA_NOT_FOUND. Found 21 Sep 2026.
    spark.sql("USE CATALOG " + catalog)
    report, step = {}, ""
    try:
        for s in SCHEMAS:
            step = "schema " + s
            spark.sql("CREATE SCHEMA IF NOT EXISTS " + catalog + "." + s)
        for v in VOLUMES:
            step = "volume " + v
            spark.sql("CREATE VOLUME IF NOT EXISTS " + catalog + "." + v)
        for name in TABLE_ORDER + VIEW_ORDER:
            step = "object " + name
            existed = spark.catalog.tableExists(catalog + "." + name)
            spark.sql(DDL[name].replace("__CAT__", catalog))
            report[name] = "existed" if existed else "created"
    except Exception as e:
        raise RuntimeError("ensure_tables failed at " + step + ": " + str(e)[:300])
    return report


def preflight(spark, catalog, dbutils=None, secret_scope="genesis",
              secret_key="apify-token"):
    spark.sql("USE CATALOG " + catalog)
    problems, seen = [], {}
    for label, sql, floor in CHECKS:
        try:
            n = spark.sql(sql.replace("__CAT__", catalog)).first()[0]
        except Exception as e:
            problems.append(label + ": table missing or unreadable (" +
                            type(e).__name__ + ")")
            continue
        seen[label] = n
        if n < floor:
            problems.append(label + ": found " + str(n) + ", need at least " + str(floor))
    if dbutils is not None:
        try:
            tok = dbutils.secrets.get(scope=secret_scope, key=secret_key)
            if not tok or len(tok) < 20:
                problems.append("Apify secret " + secret_scope + "/" + secret_key +
                                " is empty")
            else:
                seen["apify secret readable"] = True
        except Exception as e:
            problems.append("Apify secret " + secret_scope + "/" + secret_key +
                            " cannot be read in this workspace. Create the secret "
                            "scope here first. (" + type(e).__name__ + ")")
    if problems:
        raise RuntimeError("Agent 1 preflight failed in " + catalog +
                           ". Nothing was run.\n  - " + "\n  - ".join(problems))
    return seen
